(async()=>{
 await document.fonts.ready; await new Promise(r=>setTimeout(r,500));
 const ctx=document.createElement('canvas').getContext('2d',{willReadFrequently:true});ctx.canvas.width=ctx.canvas.height=1;
 const rgba=s=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=s;ctx.fillRect(0,0,1,1);return [...ctx.getImageData(0,0,1,1).data]};
 const over=(a,b)=>{const t=a[3]/255;return a.slice(0,3).map((c,i)=>Math.round(c*t+b[i]*(1-t))).concat(255)};
 const bg=e=>{if(!e)return [255,255,255,255];return over(rgba(getComputedStyle(e).backgroundColor),bg(e.parentElement))};
 const lum=c=>c.slice(0,3).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((s,x,i)=>s+x*[.2126,.7152,.0722][i],0);
 const contrast=(a,b)=>(Math.max(lum(a),lum(b))+.05)/(Math.min(lum(a),lum(b))+.05);
 const names=['Search files','Refresh','Actions for Meeting notes.txt','Sign out','Trash','New','Close','Done'];
 const els=[...document.querySelectorAll('input,select,button')].filter(e=>names.includes(e.getAttribute('aria-label')||e.textContent?.trim()) || (e.closest('dialog')&&['INPUT','SELECT'].includes(e.tagName)));
 return {at:new Date().toISOString(),viewport:{width:innerWidth,height:innerHeight},dpr:devicePixelRatio,os:matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light',data_theme:document.documentElement.dataset.theme??null,saved_theme:localStorage.getItem('ky_theme'),overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,passwordFields:document.querySelectorAll('input[type=password]').length,controls:els.map(e=>{
 const s=getComputedStyle(e),r=e.getBoundingClientRect(),fill=bg(e),adj=bg(e.parentElement),border=over(rgba(s.borderTopColor),fill);
 const label=e.id?[...document.querySelectorAll('label')].find(l=>l.htmlFor===e.id)?.textContent:null;
 return {element:e.tagName,label:e.getAttribute('aria-label')||label||e.closest('label')?.textContent?.trim()||e.textContent.trim(),type:e.type,class:e.className,state:{focused:e===document.activeElement,focusVisible:e.matches(':focus-visible'),hovered:e.matches(':hover'),disabled:e.disabled},bounds:{x:r.x,y:r.y,width:r.width,height:r.height},border_css:s.borderTopColor,border_width:s.borderTopWidth,background_css:s.backgroundColor,parent_background_css:getComputedStyle(e.parentElement).backgroundColor,fill_srgb:fill,adjacent_srgb:adj,border_srgb:border,border_to_fill:contrast(border,fill),border_to_adjacent:contrast(border,adj),field_token:s.getPropertyValue('--ky-field-border').trim(),matching_border_rules:[...document.styleSheets].flatMap(sh=>{try{return [...sh.cssRules]}catch{return []}}).filter(rule=>rule.selectorText&&(rule.style?.border||rule.style?.borderColor)&&(()=>{try{return e.matches(rule.selectorText)}catch{return false}})()).map(rule=>({selector:rule.selectorText,border:rule.style.border,borderColor:rule.style.borderColor}))}
 })};
})()

